  const openApprovalModal = (item) => {
    if (item.category === 'leave' || item.raw?.type === 'leave' || item.targetTab === 'hr-payroll') {
      setHrInitialTab('Attendance');
      setHrInitialAdding(false);
      setActiveTab('hr-payroll');
      return;
    }
    setViewingApproval(item);
    setApprovalSubmitting(false);
    setApprovalCommentDraft(item.comment || item.raw?.comment || '');
    const initialQuantities = {};
    const initialSellingPrices = {};
    let items = item.raw?.details?.items || [];
    const isVendor = item.category === 'vendor_onboarding' || item.raw?.type === 'vendor_onboarding' || item.type === 'vendor_onboarding';
    if (isVendor && (!items || items.length === 0)) {
      const vId = item.raw?.details?.vendorId;
      const vCode = item.raw?.details?.vendorCode;
      const matchedVendor = vendors.find(v => (vId && v._id === vId) || (vCode && v.code === vCode) || (item.title && v.name && item.title.toLowerCase().includes(v.name.toLowerCase())));
      if (matchedVendor && Array.isArray(matchedVendor.medicines) && matchedVendor.medicines.length > 0) {
        items = matchedVendor.medicines;
      }
    }
    items.forEach((it, idx) => {
      const defaultQty = (it.approvedQty !== null && it.approvedQty !== undefined) ? Number(it.approvedQty) : Number(it.requiredQty || 0);
      initialQuantities[idx] = defaultQty;
      if (it.name) initialQuantities[it.name.trim().toLowerCase()] = defaultQty;
      if (it._id) initialQuantities[String(it._id)] = defaultQty;
      if (it.itemId) initialQuantities[String(it.itemId)] = defaultQty;

      // Initialize default selling price / MRP for vendor onboarding review
      const purchasePrice = Number(it.price || it.purchasePrice || 0);
      const defaultMrp = it.sellingPrice || it.mrp || (purchasePrice > 0 ? Math.round(purchasePrice * 1.25 * 100) / 100 : purchasePrice);
      initialSellingPrices[idx] = defaultMrp;
      if (it.sku) initialSellingPrices[it.sku.trim().toUpperCase()] = defaultMrp;
      if (it.name) initialSellingPrices[it.name.trim().toLowerCase()] = defaultMrp;
    });
    setApprovalItemsDraft(initialQuantities);
    setApprovalSellingPricesDraft(initialSellingPrices);
  };
