  const fetchStaff = async () => {
    setDomainLoading('staff', true);
    try {
      const [usersRes, leavesRes] = await Promise.allSettled([
        api.get('/admin/users'),
        api.get('/hr/leaves')
      ]);
      
      const usersData = usersRes.status === 'fulfilled' && Array.isArray(usersRes.value?.data) ? usersRes.value.data : [];
      const leavesData = leavesRes.status === 'fulfilled' && Array.isArray(leavesRes.value?.data) ? leavesRes.value.data : [];
      setServerLeaves(leavesData);

      const formatLastLogin = (dateString) => {
        if (!dateString) return 'Never';
        const date = new Date(dateString);
        const today = new Date();
        const isToday = date.getDate() === today.getDate() &&
                        date.getMonth() === today.getMonth() &&
                        date.getFullYear() === today.getFullYear();
        const timeStr = date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit', hour12: true });
        return isToday ? `Today ${timeStr}` : `${date.toLocaleDateString([], { month: 'short', day: 'numeric' })} ${timeStr}`;
      };

      const dbUsers = usersData.map(user => {
        let initials = user.name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
        if (!initials) initials = 'ST';
        let avatarColor = 'blue';
        if (user.role === 'doctor') avatarColor = 'purple';
        if (user.role === 'receptionist') avatarColor = 'gold';
        if (user.role === 'hr') avatarColor = 'teal';
        return {
          id: user._id || user.id,
          name: user.name,
          role: user.role,
          dept: user.department || user.specialty || (user.role === 'doctor' ? 'General Medicine' : user.role === 'hr' ? 'Hospital Administration' : 'Administration'),
          department: user.department || user.specialty || (user.role === 'doctor' ? 'General Medicine' : user.role === 'hr' ? 'Hospital Administration' : 'Administration'),
          designation: user.designation || (user.role === 'doctor' ? 'Consultant Practitioner' : user.role === 'hr' ? 'HR Manager' : (user.role ? user.role.charAt(0).toUpperCase() + user.role.slice(1) : 'Staff Member')),
          joined: user.createdAt ? new Date(user.createdAt).toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' }) : 'Recently',
          createdAt: user.createdAt,
          joiningDate: user.joiningDate || user.createdAt,
          gender: user.gender || '',
          bloodGroup: user.bloodGroup || '',
          employmentType: user.employmentType || 'Full-Time',
          workLocation: user.workLocation || 'Main Wing',
          shiftName: user.shiftName || 'General Shift',
          patientsToday: '0',
          lastLogin: formatLastLogin(user.lastLogin),
          workingDays: getWorkingDaysString(user.weeklyOff),
          status: 'Active',
          active: true,
          initials,
          avatarColor,
          max_slots: user.max_slots,
          email: user.email || '',
          phone: user.phone || '',
          consultationFee: user.consultationFee !== undefined ? user.consultationFee : 500,
          doctorSlots: user.doctorSlots || [],
          password: '',
          staff_id: user.staff_id || '',
          weeklyOff: user.weeklyOff || ''
        };
      });
      setStaff(dbUsers);
    } catch (err) {
      console.error('Failed to fetch staff', err);
    } finally {
      setDomainLoading('staff', false);
    }
  };

